from django.db import migrations


def backfill_action_project_id(apps, schema_editor):
    """把 Action.project_id 回填为它所属 CaseUI 的 project_id"""
    Action = apps.get_model("case_ui", "Action")
    CaseUIAction = apps.get_model("case_ui", "CaseUIAction")
    updated = 0
    for action in Action.objects.all():
        link = (
            CaseUIAction.objects.filter(action_id_id=action.id)
            .order_by("sort")
            .first()
        )
        if link is not None:
            project_id = link.caseui_id.project_id_id
            if project_id != action.project_id_id:
                action.project_id_id = project_id
                action.save(update_fields=["project_id_id"])
                updated += 1
    print(f"backfilled {updated} action(s)")


def noop(apps, schema_editor):
    pass


